/* THE GLYPHS, FROM THE FILES INTO ONE SCRIPT THE PAGE CAN HOLD.
 *
 *   node tools/icons.mjs            writes ui/icons.js from tools/icons/*.svg
 *   node tools/icons.mjs --check    prints nothing and exits 1 if the two disagree
 *
 * WHY A GENERATED FILE AND NOT THE SVGs THEMSELVES. The page's own Content-Security-Policy is
 * `default-src 'none'; img-src data:`, so an `<img src="icons/menu.svg">` is refused and a
 * fetch() of a file: URL cannot work at all; an inline <svg> is the one form the page may
 * paint. The drawings therefore have to reach the renderer as script, and a script that is
 * generated from the files is the only arrangement where the files stay the source of truth.
 *
 * WHY tools/ AND NOT ui/. electron-builder ships `ui/**` and no part of `tools/`, so the SVGs
 * under tools/icons/ are the repository's copy of the set and ui/icons.js is what a customer's
 * machine gets: one file rather than 105 that nothing at runtime would ever open.
 *
 * EACH FILE'S OWN ROOT ATTRIBUTES ARE KEPT, rather than a wrapper of this script's making.
 * Most of the set are stroke icons at width 1.75, backup.svg is drawn at 20 px with its line at
 * 1.4, and favourite.svg is a filled star with no stroke attributes at all, so a uniform wrapper
 * would have drawn both wrong and nothing would have said so. The one thing added is `class="ic" aria-hidden="true" focusable="false"`:
 * the size is the stylesheet's, and a glyph beside its own word must not be read out twice.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const FROM = path.join(ROOT, "tools", "icons");
const TO = path.join(ROOT, "ui", "icons.js");

/** The set, name to the markup the page paints, in the order a reader would look for it. */
export function build() {
  const names = fs.readdirSync(FROM).filter(f => f.endsWith(".svg"))
    .map(f => f.slice(0, -4)).sort();
  const out = new Map();
  for (const name of names) {
    let svg = fs.readFileSync(path.join(FROM, name + ".svg"), "utf8").trim();
    if (!svg.startsWith("<svg ") || !svg.endsWith("</svg>"))
      throw new Error(name + ".svg is not one <svg> element");
    if (/#[0-9a-fA-F]{3,6}|rgb\(|url\(/.test(svg))
      throw new Error(name + ".svg carries a colour of its own");
    if (svg.indexOf("\n") >= 0) throw new Error(name + ".svg is more than one line");
    svg = svg.replace("<svg ", '<svg class="ic" aria-hidden="true" focusable="false" ');
    out.set(name, svg);
  }
  return out;
}

export function source() {
  const set = build();
  const rows = [...set].map(([n, svg]) =>
    "    " + JSON.stringify(n) + ": " + JSON.stringify(svg) + ",").join("\n");
  return '"use strict";\n'
    + "/* GENERATED BY tools/icons.mjs FROM tools/icons/*.svg. Do not edit: edit the SVG and run\n"
    + "   `node tools/icons.mjs` again. tests/icons.mjs holds this file against that folder.\n"
    + "\n"
    + "   The set is Claude Fable 5.1's, drawn on a 24 grid with a 1.75 stroke and round caps,\n"
    + "   chosen by Maxim on 2026-09-17 against a second house's set and approved wholesale on\n"
    + "   2026-09-18. What each glyph is for is tools/icons/index.md, one line per name; a button\n"
    + "   wearing one the index does not name for it is the failure that list exists to prevent.\n"
    + "\n"
    + "   EVERY GLYPH IS DRAWN IN currentColor, so it takes the ink of whatever it sits in and\n"
    + "   there is no colour here to restep for the dark theme. */\n"
    + "(function () {\n"
    + "  const ICONS = {\n" + rows + "\n  };\n"
    + "  /* An unknown name paints nothing rather than throwing: a glyph is never the reason a\n"
    + "     screen fails to paint. tests/icons.mjs reads every name ui/app.js asks for out of its\n"
    + "     source and fails on one this file has not got, which is where a typo is caught. */\n"
    + "  window.STUDIO_ICONS = {\n"
    + "    html(name) { return Object.prototype.hasOwnProperty.call(ICONS, name) ? ICONS[name] : \"\"; },\n"
    + "    names() { return Object.keys(ICONS); },\n"
    + "  };\n"
    + "})();\n";
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const want = source();
  if (process.argv.indexOf("--check") > -1) {
    const have = fs.existsSync(TO) ? fs.readFileSync(TO, "utf8") : "";
    if (have !== want) { console.error("ui/icons.js is not what tools/icons/ says it should be"); process.exit(1); }
    console.log("ui/icons.js is current: " + build().size + " glyphs");
  } else {
    fs.writeFileSync(TO, want, "utf8");
    console.log("wrote ui/icons.js: " + build().size + " glyphs from tools/icons/");
  }
}
